from collections import deque

def solve_checkpoint_route(text):
    tokens = text.split()
    rows, cols = int(tokens[0]), int(tokens[1])
    grid = tokens[2:2 + rows]
    where = {}
    for i, row in enumerate(grid):
        for j, ch in enumerate(row):
            if ch in 'SCE':
                where[ch] = (i, j)

    def steps(src, dst):
        dist = [[-1] * cols for _ in range(rows)]
        dist[src[0]][src[1]] = 0
        queue = deque([src])
        while queue:
            i, j = queue.popleft()
            if (i, j) == dst:
                return dist[i][j]
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and dist[a][b] < 0 and grid[a][b] != '#':
                    dist[a][b] = dist[i][j] + 1
                    queue.append((a, b))
        return -1

    first = steps(where['S'], where['C'])
    second = steps(where['C'], where['E'])
    if first < 0 or second < 0:
        return '-1'
    return str(first + second)

